package chainledger

import (
	"encoding/json"
	"reflect"
	"strings"
	"testing"
)

// compareDoc builds a lineage document from names and directed dependencies,
// so tests can freely reorder or repeat nodes and edges without hand-writing
// JSON.
func compareDoc(t *testing.T, nodes []string, edges [][2]string) string {
	t.Helper()
	type edge struct {
		From string `json:"from"`
		To   string `json:"to"`
	}
	doc := struct {
		Nodes []string `json:"nodes"`
		Edges []edge   `json:"edges"`
	}{Nodes: nodes}
	for _, e := range edges {
		doc.Edges = append(doc.Edges, edge{From: e[0], To: e[1]})
	}
	data, err := json.Marshal(doc)
	if err != nil {
		t.Fatalf("marshal document: %v", err)
	}
	return string(data)
}

func depPairs(deps []Dependency) [][2]string {
	pairs := make([][2]string, len(deps))
	for i, d := range deps {
		pairs[i] = [2]string{d.From, d.To}
	}
	return pairs
}

// Identical documents report no change as a success with two non-nil empty
// lists, and datasets outside the target's derivation (an independent node and
// the target's downstream) never enter either list.
func TestCompareUpstreamLineageNoChange(t *testing.T) {
	before := compareDoc(t,
		[]string{"s", "m", "t", "d", "lone"},
		[][2]string{{"s", "m"}, {"m", "t"}, {"t", "d"}})
	after := before

	diff, err := CompareUpstreamLineage(before, after, "t")
	if err != nil {
		t.Fatalf("CompareUpstreamLineage: %v", err)
	}
	if diff.Added == nil || diff.Removed == nil {
		t.Fatalf("no-change result must hold non-nil empty lists, got %+v", diff)
	}
	if len(diff.Added) != 0 || len(diff.Removed) != 0 {
		t.Fatalf("expected no change, got added=%v removed=%v", diff.Added, diff.Removed)
	}
}

// A target with no upstreams in both documents compares cleanly even while
// unrelated lineage elsewhere changes between the two documents.
func TestCompareUpstreamLineageIgnoresUnrelatedChanges(t *testing.T) {
	before := compareDoc(t, []string{"t", "x", "y"}, [][2]string{{"x", "y"}})
	// t stays a root: the changed x/y/z chain is independent, and t gains a
	// downstream, which must never enter its upstream comparison.
	after := compareDoc(t,
		[]string{"t", "x", "y", "z", "down"},
		[][2]string{{"x", "y"}, {"y", "z"}, {"t", "down"}})

	diff, err := CompareUpstreamLineage(before, after, "t")
	if err != nil {
		t.Fatalf("CompareUpstreamLineage: %v", err)
	}
	if len(diff.Added) != 0 || len(diff.Removed) != 0 {
		t.Fatalf("root target should see no change, got added=%v removed=%v",
			depPairs(diff.Added), depPairs(diff.Removed))
	}
}

// Direct dependencies added and removed at the target are reported with the
// exports' from-upstream/to-derived direction.
func TestCompareUpstreamLineageDirectAddAndRemove(t *testing.T) {
	before := compareDoc(t,
		[]string{"keep", "gone", "soon", "t"},
		[][2]string{{"keep", "t"}, {"gone", "t"}})
	after := compareDoc(t,
		[]string{"keep", "gone", "soon", "t"},
		[][2]string{{"keep", "t"}, {"soon", "t"}})

	diff, err := CompareUpstreamLineage(before, after, "t")
	if err != nil {
		t.Fatalf("CompareUpstreamLineage: %v", err)
	}
	if got, want := depPairs(diff.Added), [][2]string{{"soon", "t"}}; !reflect.DeepEqual(got, want) {
		t.Errorf("Added = %v, want %v", got, want)
	}
	if got, want := depPairs(diff.Removed), [][2]string{{"gone", "t"}}; !reflect.DeepEqual(got, want) {
		t.Errorf("Removed = %v, want %v", got, want)
	}
}

// The target reaches s both directly and through m. Removing only the longer
// route's edge m -> t must still show, and because that deletion detaches the
// whole m segment from the target's derivation, s -> m — which belonged to the
// before scope — is removed as well. Nothing is added.
func TestCompareUpstreamLineageLongRouteEdgeDeletion(t *testing.T) {
	before := compareDoc(t,
		[]string{"s", "m", "t"},
		[][2]string{{"s", "t"}, {"s", "m"}, {"m", "t"}})
	after := compareDoc(t,
		[]string{"s", "m", "t"},
		[][2]string{{"s", "t"}, {"s", "m"}})

	diff, err := CompareUpstreamLineage(before, after, "t")
	if err != nil {
		t.Fatalf("CompareUpstreamLineage: %v", err)
	}
	if len(diff.Added) != 0 {
		t.Errorf("Added = %v, want none", depPairs(diff.Added))
	}
	wantRemoved := [][2]string{{"m", "t"}, {"s", "m"}}
	if got := depPairs(diff.Removed); !reflect.DeepEqual(got, wantRemoved) {
		t.Errorf("Removed = %v, want %v", got, wantRemoved)
	}
}

// Deleting only the direct s -> t edge keeps the longer route intact, so just
// the direct relationship is removed and the route's edges stay common.
func TestCompareUpstreamLineageDirectEdgeDeletionKeepsRoute(t *testing.T) {
	before := compareDoc(t,
		[]string{"s", "m", "t"},
		[][2]string{{"s", "t"}, {"s", "m"}, {"m", "t"}})
	after := compareDoc(t,
		[]string{"s", "m", "t"},
		[][2]string{{"s", "m"}, {"m", "t"}})

	diff, err := CompareUpstreamLineage(before, after, "t")
	if err != nil {
		t.Fatalf("CompareUpstreamLineage: %v", err)
	}
	if got, want := depPairs(diff.Removed), [][2]string{{"s", "t"}}; !reflect.DeepEqual(got, want) {
		t.Errorf("Removed = %v, want %v", got, want)
	}
	if len(diff.Added) != 0 {
		t.Errorf("Added = %v, want none", depPairs(diff.Added))
	}
}

// The target's direct upstreams do not change — it still derives from m — but
// m's own source swaps from old to new. The actual changed dependencies show,
// proving the comparison is over the full upstream scope rather than the
// target's direct upstream list.
func TestCompareUpstreamLineageAncestorSourceSwap(t *testing.T) {
	before := compareDoc(t,
		[]string{"old", "new", "m", "t"},
		[][2]string{{"m", "t"}, {"old", "m"}})
	after := compareDoc(t,
		[]string{"old", "new", "m", "t"},
		[][2]string{{"m", "t"}, {"new", "m"}})

	diff, err := CompareUpstreamLineage(before, after, "t")
	if err != nil {
		t.Fatalf("CompareUpstreamLineage: %v", err)
	}
	if got, want := depPairs(diff.Added), [][2]string{{"new", "m"}}; !reflect.DeepEqual(got, want) {
		t.Errorf("Added = %v, want %v", got, want)
	}
	if got, want := depPairs(diff.Removed), [][2]string{{"old", "m"}}; !reflect.DeepEqual(got, want) {
		t.Errorf("Removed = %v, want %v", got, want)
	}
}

// A new multi-hop branch appearing is reported edge by edge, and results are
// ordered by From then To in Go string order regardless of document order.
func TestCompareUpstreamLineageNewBranchOrdering(t *testing.T) {
	// Before: a -> t only. After adds b -> mid -> t. Nodes and edges are listed
	// shuffled and partly repeated in the after document.
	before := compareDoc(t,
		[]string{"a", "b", "mid", "t"},
		[][2]string{{"a", "t"}})
	after := `{"edges":[{"from":"mid","to":"t"},{"from":"b","to":"mid"},{"from":"a","to":"t"},{"from":"b","to":"mid"}],` +
		`"nodes":["t","a","mid","b","a"]}`

	diff, err := CompareUpstreamLineage(before, after, "t")
	if err != nil {
		t.Fatalf("CompareUpstreamLineage: %v", err)
	}
	wantAdded := [][2]string{{"b", "mid"}, {"mid", "t"}}
	if got := depPairs(diff.Added); !reflect.DeepEqual(got, wantAdded) {
		t.Errorf("Added = %v, want %v", got, wantAdded)
	}
	if len(diff.Removed) != 0 {
		t.Errorf("Removed = %v, want none", depPairs(diff.Removed))
	}
}

// Both lists sort by From first and then To; duplicate edges in the documents
// never duplicate an entry.
func TestCompareUpstreamLineageSortsByFromThenTo(t *testing.T) {
	before := compareDoc(t,
		[]string{"z", "a", "m", "t"},
		[][2]string{{"z", "t"}, {"z", "m"}, {"m", "t"}})
	after := compareDoc(t,
		[]string{"z", "a", "m", "t"},
		[][2]string{
			{"z", "t"}, {"z", "m"}, {"m", "t"}, // survivors
			{"a", "t"}, {"a", "m"}, // added, both From a: order on To
		})

	diff, err := CompareUpstreamLineage(before, after, "t")
	if err != nil {
		t.Fatalf("CompareUpstreamLineage: %v", err)
	}
	wantAdded := [][2]string{{"a", "m"}, {"a", "t"}}
	if got := depPairs(diff.Added); !reflect.DeepEqual(got, wantAdded) {
		t.Errorf("Added = %v, want %v", got, wantAdded)
	}
}

// Names compare by their exact decoded value: case and surrounding spaces
// matter, so a relationship renamed only by case or whitespace is a real
// remove/add pair.
func TestCompareUpstreamLineageExactNameMatching(t *testing.T) {
	before := compareDoc(t, []string{" mid ", "t"}, [][2]string{{" mid ", "t"}})
	after := compareDoc(t, []string{" mid ", "Mid", "t"}, [][2]string{{"Mid", "t"}})

	diff, err := CompareUpstreamLineage(before, after, "t")
	if err != nil {
		t.Fatalf("CompareUpstreamLineage: %v", err)
	}
	if got, want := depPairs(diff.Added), [][2]string{{"Mid", "t"}}; !reflect.DeepEqual(got, want) {
		t.Errorf("Added = %v, want %v", got, want)
	}
	if got, want := depPairs(diff.Removed), [][2]string{{" mid ", "t"}}; !reflect.DeepEqual(got, want) {
		t.Errorf("Removed = %v, want %v", got, want)
	}
}

// An empty target is rejected without either document being inspected first:
// even malformed documents yield the missing-target error.
func TestCompareUpstreamLineageEmptyTarget(t *testing.T) {
	_, err := CompareUpstreamLineage("not json", "also not json", "")
	if err == nil || err.Error() != "target dataset name is required" {
		t.Fatalf("error = %v, want target dataset name is required", err)
	}
}

// A target missing from either valid document fails the whole comparison with
// the target named and the offending document identified, and no partial
// lists.
func TestCompareUpstreamLineageTargetNotRegistered(t *testing.T) {
	withT := compareDoc(t, []string{"s", "t"}, [][2]string{{"s", "t"}})
	withoutT := compareDoc(t, []string{"s"}, nil)

	if _, err := CompareUpstreamLineage(withoutT, withT, "t"); err == nil {
		t.Fatal("expected error when target missing from before document")
	} else {
		msg := err.Error()
		if !strings.Contains(msg, "t") || !strings.Contains(msg, "before-change") {
			t.Fatalf("error %q must name the target and the before-change document", msg)
		}
	}

	if _, err := CompareUpstreamLineage(withT, withoutT, "t"); err == nil {
		t.Fatal("expected error when target missing from after document")
	} else {
		msg := err.Error()
		if !strings.Contains(msg, "t") || !strings.Contains(msg, "after-change") {
			t.Fatalf("error %q must name the target and the after-change document", msg)
		}
	}
}

// A document that fails import validation is rejected as a whole; the error
// states which document (before or after) was rejected and why, and no partial
// difference comes back.
func TestCompareUpstreamLineageRejectsInvalidDocuments(t *testing.T) {
	good := compareDoc(t, []string{"s", "t"}, [][2]string{{"s", "t"}})

	cyclic := compareDoc(t,
		[]string{"a", "b", "t"},
		[][2]string{{"a", "b"}, {"b", "a"}})
	dangling := compareDoc(t,
		[]string{"t"},
		[][2]string{{"ghost", "t"}})

	if _, err := CompareUpstreamLineage(cyclic, good, "t"); err == nil {
		t.Fatal("expected rejection of cyclic before document")
	} else if msg := err.Error(); !strings.Contains(msg, "before-change") || !strings.Contains(msg, "cycle") {
		t.Fatalf("error %q must identify the before-change document and its cycle", msg)
	}

	if _, err := CompareUpstreamLineage(good, cyclic, "t"); err == nil {
		t.Fatal("expected rejection of cyclic after document")
	} else if msg := err.Error(); !strings.Contains(msg, "after-change") || !strings.Contains(msg, "cycle") {
		t.Fatalf("error %q must identify the after-change document and its cycle", msg)
	}

	if _, err := CompareUpstreamLineage(good, dangling, "t"); err == nil {
		t.Fatal("expected rejection of after document with a missing edge endpoint")
	} else if msg := err.Error(); !strings.Contains(msg, "after-change") || !strings.Contains(msg, "ghost") {
		t.Fatalf("error %q must identify the after-change document and the ghost endpoint", msg)
	}
}

// When both documents are invalid, the before document is validated first and
// its rejection is the one reported. Document validation also precedes target
// presence checks.
func TestCompareUpstreamLineageValidatesBeforeFirst(t *testing.T) {
	cyclic := compareDoc(t, []string{"a"}, [][2]string{{"a", "a"}})
	// Target also absent from both documents; document rejection must win.
	if _, err := CompareUpstreamLineage(cyclic, cyclic, "ghost"); err == nil {
		t.Fatal("expected before-document rejection")
	} else if msg := err.Error(); !strings.HasPrefix(msg, "before-change") {
		t.Fatalf("error %q must be the before-document rejection", msg)
	}
}

// The comparison only builds throwaway graphs and never mutates or depends on
// the caller's own graph: passing documents round-trips through import with no
// shared state, and calling twice yields identical results.
func TestCompareUpstreamLineageDeterministic(t *testing.T) {
	before := compareDoc(t,
		[]string{"o", "n", "m", "t"},
		[][2]string{{"o", "m"}, {"m", "t"}})
	after := compareDoc(t,
		[]string{"o", "n", "m", "t"},
		[][2]string{{"n", "m"}, {"m", "t"}})

	first, err := CompareUpstreamLineage(before, after, "t")
	if err != nil {
		t.Fatalf("first comparison: %v", err)
	}
	second, err := CompareUpstreamLineage(before, after, "t")
	if err != nil {
		t.Fatalf("second comparison: %v", err)
	}
	if !reflect.DeepEqual(first, second) {
		t.Fatalf("comparisons differ:\n%+v\n%+v", first, second)
	}
	if got, want := depPairs(first.Added), [][2]string{{"n", "m"}}; !reflect.DeepEqual(got, want) {
		t.Errorf("Added = %v, want %v", got, want)
	}
	if got, want := depPairs(first.Removed), [][2]string{{"o", "m"}}; !reflect.DeepEqual(got, want) {
		t.Errorf("Removed = %v, want %v", got, want)
	}
}

package chainledger

import (
	"reflect"
	"strings"
	"testing"
)

// exportReregisterScenario builds the regression lineage: raw derives a and b,
// b derives c; mid depends directly on raw, a, c and old; old depends on the
// independent source oldroot. report depends on mid and derives view, while
// isolated stands alone.
func exportReregisterScenario(t *testing.T) map[string]*Lineage {
	t.Helper()
	return buildRegisteredGraph(t, [][]string{
		{"raw"},
		{"a", "raw"},
		{"b", "raw"},
		{"c", "b"},
		{"oldroot"},
		{"old", "oldroot"},
		{"mid", "raw", "a", "c", "old"},
		{"report", "mid"},
		{"view", "report"},
		{"isolated"},
	})
}

// The exact JSON texts before and after mid's direct upstreams are replaced by
// a and c. Both orderings are fully determined by the names.
const (
	exportReregisterBefore = `{"nodes":["a","b","c","mid","old","oldroot","raw","report"],` +
		`"edges":[{"from":"a","to":"mid"},{"from":"b","to":"c"},` +
		`{"from":"c","to":"mid"},{"from":"mid","to":"report"},` +
		`{"from":"old","to":"mid"},{"from":"oldroot","to":"old"},` +
		`{"from":"raw","to":"a"},{"from":"raw","to":"b"},` +
		`{"from":"raw","to":"mid"}]}`
	exportReregisterAfter = `{"nodes":["a","b","c","mid","raw","report"],` +
		`"edges":[{"from":"a","to":"mid"},{"from":"b","to":"c"},` +
		`{"from":"c","to":"mid"},{"from":"mid","to":"report"},` +
		`{"from":"raw","to":"a"},{"from":"raw","to":"b"}]}`
)

// Regression for exporting after a same-name Register replaced an intermediate
// dataset's whole direct-upstream list. Re-registering mid with a and c drops
// the direct raw -> mid and old -> mid edges, but raw still derives report
// through TWO surviving branches — the short raw -> a -> mid -> report route
// and the longer raw -> b -> c -> mid -> report route — so the export must
// keep raw, a, b, c, mid and report with every surviving direct dependency,
// not just the shortest path. old and oldroot no longer take part in report's
// derivation and leave the document together with their edges, while their
// registrations and the oldroot -> old dependency stay in the graph. view and
// isolated never enter report's upstream document.
func TestExportUpstreamLineageAfterReregister(t *testing.T) {
	graph := exportReregisterScenario(t)
	assertConsistent(t, graph)

	// The export before the replacement covers the full ancestor closure,
	// old and oldroot included.
	if out := mustExport(t, graph, "report"); out != exportReregisterBefore {
		t.Errorf("export before re-register =\n%s\nwant:\n%s", out, exportReregisterBefore)
	}

	// Replace mid's whole direct-upstream list; report's own registration is
	// not part of the request and must stay as it was.
	mustRegister(t, graph, "mid", "a", "c")
	assertConsistent(t, graph)
	assertEntry(t, graph, "mid", []string{"a", "c"}, []string{"report"})
	assertEntry(t, graph, "report", []string{"mid"}, []string{"view"})
	// old and oldroot keep their registrations and their mutual dependency;
	// old only lost the removed reverse edge to mid.
	assertEntry(t, graph, "old", []string{"oldroot"}, nil)
	assertEntry(t, graph, "oldroot", nil, []string{"old"})
	assertEntry(t, graph, "raw", nil, []string{"a", "b"})

	before := snapshotExportGraph(graph)
	out := mustExport(t, graph, "report")
	if out != exportReregisterAfter {
		t.Errorf("export after re-register =\n%s\nwant:\n%s", out, exportReregisterAfter)
	}
	doc := parseExport(t, out)

	// Every surviving branch participates: raw reaches report through a AND
	// through b -> c, so all of raw, a, b, c, mid stay listed exactly once.
	wantNodes := []string{"a", "b", "c", "mid", "raw", "report"}
	if !reflect.DeepEqual(doc.Nodes, wantNodes) {
		t.Errorf("nodes = %v, want %v", doc.Nodes, wantNodes)
	}
	wantEdges := [][2]string{
		{"a", "mid"},
		{"b", "c"},
		{"c", "mid"},
		{"mid", "report"},
		{"raw", "a"},
		{"raw", "b"},
	}
	if got := exportEdgeNames(doc); !reflect.DeepEqual(got, wantEdges) {
		t.Errorf("edges = %v, want %v", got, wantEdges)
	}

	// The dropped raw -> mid direct edge is gone, but raw itself must not
	// follow it out of the document.
	for _, e := range doc.Edges {
		if e.From == "raw" && e.To == "mid" {
			t.Errorf("dropped direct edge raw -> mid survived in %v", doc.Edges)
		}
	}
	// old and oldroot left report's derivation entirely; view and isolated
	// were never part of it.
	for _, excluded := range []string{"old", "oldroot", "view", "isolated"} {
		for _, node := range doc.Nodes {
			if node == excluded {
				t.Errorf("nodes must not contain %q: %v", excluded, doc.Nodes)
			}
		}
	}

	// The export is read-only over the post-replacement state.
	assertGraphUnchanged(t, before, graph)
}

// The replacement's declared upstream order cannot change the exported text:
// re-registering mid with [a c] or [c a] yields byte-identical documents, as
// does building the same final lineage with a different registration order.
func TestExportUpstreamLineageAfterReregisterOrderIndependent(t *testing.T) {
	first := exportReregisterScenario(t)
	mustRegister(t, first, "mid", "a", "c")

	second := buildRegisteredGraph(t, [][]string{
		{"isolated"},
		{"oldroot"},
		{"old", "oldroot"},
		{"raw"},
		{"b", "raw"},
		{"c", "b"},
		{"a", "raw"},
		{"mid", "old", "c", "raw", "a"}, // different list order before replacement
		{"report", "mid"},
		{"view", "report"},
	})
	mustRegister(t, second, "mid", "c", "a") // replacement list flipped

	if got, want := mustExport(t, first, "report"), mustExport(t, second, "report"); got != want {
		t.Errorf("replacement list order changed the export:\nfirst:  %s\nsecond: %s", got, want)
	}
	if got := mustExport(t, first, "report"); got != exportReregisterAfter {
		t.Errorf("export =\n%s\nwant:\n%s", got, exportReregisterAfter)
	}
}

// A rejected replacement must not partially apply: re-registering mid with the
// registered isolated followed by the unregistered ghost fails naming ghost,
// and mid — plus every related node — keeps its pre-request parents, children
// and list orders. A later export of report is byte-identical to the
// pre-request text and contains neither isolated nor any partial new relation.
func TestExportUpstreamLineageFailedReregisterLeavesExportUntouched(t *testing.T) {
	graph := exportReregisterScenario(t)
	assertConsistent(t, graph)

	exportBefore := mustExport(t, graph, "report")
	if exportBefore != exportReregisterBefore {
		t.Fatalf("export before failed re-register =\n%s\nwant:\n%s", exportBefore, exportReregisterBefore)
	}
	before := snapshotExportGraph(graph)

	err := Register(graph, Dataset{Name: "mid"}, []string{"isolated", "ghost"})
	if err == nil || !strings.Contains(err.Error(), "ghost") {
		t.Fatalf("want unknown-parent error naming ghost, got %v", err)
	}

	// No partial effect: the whole graph, list orders included, is exactly as
	// before the request; mid never gained isolated nor lost any upstream.
	assertGraphUnchanged(t, before, graph)
	assertEntry(t, graph, "mid", []string{"raw", "a", "c", "old"}, []string{"report"})
	assertEntry(t, graph, "isolated", nil, nil)
	assertEntry(t, graph, "raw", nil, []string{"a", "b", "mid"})
	assertEntry(t, graph, "old", []string{"oldroot"}, []string{"mid"})
	assertConsistent(t, graph)

	// The export after the rejected request matches the pre-request text
	// exactly, with no trace of isolated or a half-applied replacement.
	exportAfter := mustExport(t, graph, "report")
	if exportAfter != exportBefore {
		t.Errorf("export changed after rejected re-register:\nbefore: %s\nafter:  %s",
			exportBefore, exportAfter)
	}
	if strings.Contains(exportAfter, "isolated") {
		t.Errorf("export must not contain isolated after the rejected request: %s", exportAfter)
	}
	assertGraphUnchanged(t, before, graph)
}

// Command compare-upstream-lineage-example demonstrates the chainledger
// lineage library's upstream lineage comparison: given two lineage JSON
// documents (the lineage before and after a change) and a target dataset name,
// CompareUpstreamLineage reports which of the target's complete upstream
// dependencies were added and which removed.
//
// This is a library feature, not a command-line query: both documents and the
// target name are fixed in code. Run it from the repository root with:
//
//	go run ./examples/compare-upstream-lineage
package main

import (
	"fmt"
	"os"

	"github.com/asdhoaiqqq/chainledger-governance/chainledger"
)

func main() {
	// Scenario 1: s reaches t both directly and through the longer route
	// s -> m -> t. The change deletes only the longer route's last edge m -> t;
	// the direct s -> t relation survives. The comparison must still report
	// m -> t, and because that deletion detaches the whole m segment from t's
	// derivation, s -> m (which belonged to t's before scope) is removed too.
	before := `{
	  "nodes": ["s", "m", "t", "view", "lone"],
	  "edges": [
	    {"from": "s", "to": "t"},
	    {"from": "s", "to": "m"},
	    {"from": "m", "to": "t"},
	    {"from": "t", "to": "view"}
	  ]
	}`
	after := `{
	  "nodes": ["s", "m", "t", "view", "lone"],
	  "edges": [
	    {"from": "s", "to": "t"},
	    {"from": "s", "to": "m"},
	    {"from": "t", "to": "view"}
	  ]
	}`
	show("longer route truncated (s -> t direct survives, s -> m -> t dropped)", before, after, "t")

	// Scenario 2: t's direct upstreams do not change — it still derives from m
	// — but m's own source is swapped from old to new. The actual changed
	// dependencies show even though t's direct upstream list is identical.
	swappedBefore := `{"nodes":["old","new","m","t"],"edges":[` +
		`{"from":"m","to":"t"},{"from":"old","to":"m"}]}`
	swappedAfter := `{"nodes":["old","new","m","t"],"edges":[` +
		`{"from":"m","to":"t"},{"from":"new","to":"m"}]}`
	show("ancestor source swapped while t's direct upstreams stay m", swappedBefore, swappedAfter, "t")

	// No change is a success with two empty lists, never a failure.
	unchanged := `{"nodes":["a","t"],"edges":[{"from":"a","to":"t"}]}`
	show("nothing changed", unchanged, unchanged, "t")

	// Failures identify the cause and, for documents, which one was rejected.
	fail := func(label, beforeText, afterText, target string) {
		_, err := chainledger.CompareUpstreamLineage(beforeText, afterText, target)
		if err == nil {
			fmt.Fprintf(os.Stderr, "%s unexpectedly succeeded\n", label)
			os.Exit(1)
		}
		fmt.Printf("%s:\n  refused: %v\n\n", label, err)
	}
	good := unchanged
	cyclic := `{"nodes":["x"],"edges":[{"from":"x","to":"x"}]}`
	notThere := `{"nodes":["a"],"edges":[]}`
	fail("empty target name", good, good, "")
	fail("target missing from the before document", notThere, good, "t")
	fail("target missing from the after document", good, notThere, "t")
	fail("after document carries a self-dependency cycle", good, cyclic, "t")
}

func show(label, before, after, target string) {
	diff, err := chainledger.CompareUpstreamLineage(before, after, target)
	if err != nil {
		fmt.Fprintf(os.Stderr, "CompareUpstreamLineage(%q): %v\n", target, err)
		os.Exit(1)
	}
	fmt.Printf("%s:\n", label)
	fmt.Printf("  added   (%d):\n", len(diff.Added))
	for _, d := range diff.Added {
		fmt.Printf("    %s -> %s\n", d.From, d.To)
	}
	fmt.Printf("  removed (%d):\n", len(diff.Removed))
	for _, d := range diff.Removed {
		fmt.Printf("    %s -> %s\n", d.From, d.To)
	}
	fmt.Println()
}

